tape( 'if provided a BigInt, the constructor stores the lower 64 bits', function test( t ) {
	var x;

	if ( !hasBigIntSupport() ) {
		t.pass( 'environment does not support BigInt' );
		t.end();
		return;
	}
	x = new Uint64( BigInt( '18446744073709551616' ) );
	t.strictEqual( x.toString(), '0', 'returns expected value' );
	t.end();
});

tape( 'if provided a BigInt and a high-low flag, the constructor stores a Uint32Array', function test( t ) {
	var x;

	if ( !hasBigIntSupport() ) {
		t.pass( 'environment does not support BigInt' );
		t.end();
		return;
	}
	x = new Uint64( BigInt( '18446744073709551616' ), true );
	t.strictEqual( isUint32Array( x.value ), true, 'returns expected value' );
	t.deepEqual( [ x.value[ 0 ], x.value[ 1 ] ], [ 0, 0 ], 'returns expected value' );
	t.end();
});

tape( 'if provided a Uint32Array of length 2 and no high-low flag, the constructor stores the expected numeric value', function test( t ) {
	var x;

	x = new Uint64( new Uint32Array( [ 1, 2 ] ) );
	t.strictEqual( x.toString(), '4294967298', 'returns expected value' );
	t.end();
});

tape( 'if provided a Uint32Array of length 2 and a high-low flag, the constructor stores a Uint32Array value', function test( t ) {
	var x;

	x = new Uint64( new Uint32Array( [ 1, 2 ] ), true );
	t.strictEqual( isUint32Array( x.value ), true, 'returns expected value' );
	t.deepEqual( [ x.value[ 0 ], x.value[ 1 ] ], [ 1, 2 ], 'returns expected value' );
	t.end();
});

tape( 'if provided a Uint32Array which does not have length 2, the constructor throws an error', function test( t ) {
	t.throws( badValue, TypeError, 'throws an error' );
	t.end();

	function badValue() {
		var x = new Uint64( new Uint32Array( 1 ) ); // eslint-disable-line no-unused-vars
	}
});

tape( 'if provided an array of length 2 and no high-low flag, the constructor stores the expected numeric value', function test( t ) {
	var x;

	x = new Uint64( [ 1, 2 ] );
	t.strictEqual( x.toString(), '4294967298', 'returns expected value' );
	t.end();
});

tape( 'if provided an array of length 2 and a high-low flag, the constructor stores a Uint32Array value', function test( t ) {
	var x;

	x = new Uint64( [ 1, 2 ], true );
	t.strictEqual( isUint32Array( x.value ), true, 'returns expected value' );
	t.deepEqual( [ x.value[ 0 ], x.value[ 1 ] ], [ 1, 2 ], 'returns expected value' );
	t.end();
});

tape( 'if provided an array of length 2 with float values, the constructor coerces words to uint32', function test( t ) {
	var x;

	x = new Uint64( [ 1.9, 2.1 ], true );
	t.deepEqual( [ x.value[ 0 ], x.value[ 1 ] ], [ 1, 2 ], 'returns expected value' );
	t.end();
});

tape( 'if provided an array with a length not equal to 2, the constructor throws an error', function test( t ) {
	t.throws( badValue, TypeError, 'throws an error' );
	t.end();

	function badValue() {
		var x = new Uint64( [ 1 ] ); // eslint-disable-line no-unused-vars
	}
});

tape( 'if provided an array containing non-number elements, the constructor throws an error', function test( t ) {
	t.throws( badValue, TypeError, 'throws an error' );
	t.end();

	function badValue() {
		var x = new Uint64( [ '1', 2 ] ); // eslint-disable-line no-unused-vars
	}
});

tape( 'if provided an array containing out-of-range numbers, the constructor throws an error', function test( t ) {
	t.throws( badValue, TypeError, 'throws an error' );
	t.end();

	function badValue() {
		var x = new Uint64( [ -1, 2 ] ); // eslint-disable-line no-unused-vars
	}
});

tape( 'if provided a valid integer-valued string and no high-low flag, the constructor stores the expected numeric value', function test( t ) {
	var x;

	x = new Uint64( '123456' );
	t.strictEqual( x.toString(), '123456', 'returns expected value' );
	t.end();
});

tape( 'if provided an invalid string and no high-low flag, the constructor throws an error', function test( t ) {
	t.throws( badValue, TypeError, 'throws an error' );
	t.end();

	function badValue() {
		var x = new Uint64( 'beep boop' ); // eslint-disable-line no-unused-vars
	}
});

tape( 'if provided a string and a high-low flag, the constructor stores the same numeric value as in BigInt mode', function test( t ) {
	var x;

	x = new Uint64( '123456', true );
	t.strictEqual( isUint32Array( x.value ), true, 'returns expected value' );
	t.deepEqual( [ x.value[ 0 ], x.value[ 1 ] ], [ 0, 123456 ], 'returns expected value' );
	t.strictEqual( x.toString(), '123456', 'returns expected value' );

	x = new Uint64( '4294967296', true );
	t.deepEqual( [ x.value[ 0 ], x.value[ 1 ] ], [ 1, 0 ], 'returns expected value' );
	t.strictEqual( x.toString(), '4294967296', 'returns expected value' );

	t.throws( badValue, TypeError, 'throws an error for invalid string' );
	t.end();

	function badValue() {
		var x = new Uint64( 'beep boop', true ); // eslint-disable-line no-unused-vars
	}
});

tape( 'if provided prefixed or whitespace-padded strings and a high-low flag, the constructor parses the expected numeric value', function test( t ) {
	// TODO: generated tests, to be refined
	var x;

	x = new Uint64( '  123456  ', true );
	t.deepEqual( [ x.value[ 0 ], x.value[ 1 ] ], [ 0, 123456 ], 'parses whitespace-padded decimal string' );
	t.strictEqual( x.toString(), '123456', 'returns expected decimal string' );

	x = new Uint64( '1234567890123', true );
	t.deepEqual( [ x.value[ 0 ], x.value[ 1 ] ], [ 287, 1912276171 ], 'parses chunked decimal string' );
	t.strictEqual( x.toString(), '1234567890123', 'preserves decimal numeric value' );

	x = new Uint64( '0x123456789abcdef0', true );
	t.deepEqual( [ x.value[ 0 ], x.value[ 1 ] ], [ 0x12345678, 0x9abcdef0 ], 'parses hexadecimal string' );
	t.strictEqual( x.toString( 16 ), '123456789abcdef0', 'returns expected hexadecimal string' );

	x = new Uint64( '0o10000000000000000', true );
	t.deepEqual( [ x.value[ 0 ], x.value[ 1 ] ], [ 1, 0 ], 'parses octal string' );
	t.strictEqual( x.toString(), '4294967296', 'returns expected decimal value for octal input' );

	x = new Uint64( '0b100000000000000000000000000000000', true );
	t.deepEqual( [ x.value[ 0 ], x.value[ 1 ] ], [ 1, 0 ], 'parses binary string' );
	t.strictEqual( x.toString(), '4294967296', 'returns expected decimal value for binary input' );

	t.end();
});

tape( 'if provided a valid number and a high-low flag, the constructor stores high-low words', function test( t ) {
	var x;

	x = new Uint64( 4294967301, true );
	t.strictEqual( isUint32Array( x.value ), true, 'returns expected value' );
	t.deepEqual( [ x.value[ 0 ], x.value[ 1 ] ], [ 1, 5 ], 'returns expected value' );
	t.end();
});

tape( 'if provided an invalid number, the constructor throws an error', function test( t ) {
	var values;
	var i;

	values = [
		-1,
		3.14,
		Number.MAX_SAFE_INTEGER + 1
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var x = new Uint64( value ); // eslint-disable-line no-unused-vars
		};
	}
});

tape( 'the constructor returns an instance which supports serializing an instance as a string', function test( t ) {
	var x;

	x = new Uint64( 5 );
	t.strictEqual( x.toString(), '5', 'returns expected value' );

	x = new Uint64( [ 1, 0 ], true );
	t.strictEqual( x.toString( 16 ), '100000000', 'returns expected value' );

	x = new Uint64( [ 0, 15 ], true );
	t.strictEqual( x.toString( 16 ), 'f', 'returns expected value' );

	x = new Uint64( [ 0, 5 ], true );
	t.strictEqual( x.toString( 10 ), '5', 'returns expected value' );

	x = new Uint64( 255 );
	t.strictEqual( x.toString(16), 'ff', 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance which supports serializing an instance as a JSON object', function test( t ) {
	var expected;
	var x;

	x = new Uint64( 5 );
	expected = {
		'type': 'Uint64',
		'value': '5'
	};
	t.deepEqual( x.toJSON(), expected, 'returns expected value' );
	t.strictEqual( JSON.stringify( x ), JSON.stringify( expected ), 'returns expected value' );

	// TODO: test array format of toJSON if applicable after review
	x = new Uint64( [ 1, 2 ], true );
	expected = {
		'type': 'Uint64',
		'value': [ 1, 2 ]
	};
	t.deepEqual( x.toJSON(), expected, 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance which supports converting an instance to a primitive value', function test( t ) {
	var x;

	x = new Uint64( 5 );
	t.strictEqual( x.valueOf(), 5, 'returns expected value' );

	x = new Uint64( [ 1, 0 ] );
	t.strictEqual( x.valueOf(), 4294967296, 'returns expected value' );

	x = new Uint64( [ 1, 0 ], true );
	t.strictEqual( x.valueOf(), -1, 'returns expected value' );

	x = new Uint64( 0 );
	t.strictEqual( x.valueOf(), 0, 'returns expected value' );

	t.end();
});

tape( 'if an environment supports `Symbol.toPrimitive`, instances expose a toPrimitive method', function test( t ) {
	var x;

	if ( !hasToPrimSymSupport() ) {
		t.pass( 'environment does not support Symbol.toPrimitive' );
		t.end();
		return;
	}
	x = new Uint64( 5 );
	t.strictEqual( x[ ToPrimitiveSymbol ]( 'number' ), 5, 'returns expected value' );
	t.end();
});

